{
  "a_sentences": [
    {
      "a_text": "P1 La question litigieuse porte sur la violation du droit fédéral par la juridiction cantonale en niant la responsabilité de l'intimée pour l'événement du 9 juillet 2022.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "P2 Selon les constatations de la juridiction cantonale, la personne assurée a remonté depuis une profondeur d'environ 100 m en à peine six minutes, alors que ses partenaires de plongée ont respecté les arrêts de décompression nécessaires sur une durée de deux heures.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "P3 L'action de l'eau sur le corps humain ne constitue pas, en règle générale, un facteur extérieur extraordinaire au sens de l'accident, de sorte que les lésions résultant d'un séjour volontaire dans l'eau ne sont pas considérées comme des accidents.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "P4 Le Tribunal fédéral a jusqu'ici refusé, en principe, la responsabilité de l'assureur-accidents pour les accidents de plongée.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "P5 Le simple changement de pression corporel dû à la descente et à la remontée normale d'un plongeur n'est pas considéré comme un facteur extérieur pertinent.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "P6 Lors d'une plongée à 100 m de profondeur, une pression supplémentaire de 0,1 bar par mètre s'exerce sur le corps et doit être compensée lors de la remontée.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "P7 Le Tribunal fédéral qualifie donc l'événement de la personne assurée, remontée à une profondeur d'environ 100 m en six minutes, de accident.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "P8 Le Tribunal fédéral renvoie la cause à l'intimée pour qu'elle examine les autres conditions du droit aux prestations, notamment une éventuelle réduction ou refus des prestations en raison d'une entreprise téméraire, point qui n'a pas été traité par la juridiction cantonale.",
      "b_propositions": ["P8"]
    }
  ]
}
